	/** Used on HotSpot / desktop LWJGL runtime (strict Java float semantics). */
	static float gamma22Java(int byteValue) {
		return GAMMA_2_2_JAVA[byteValue & 255];
	}

	/** Used in the TeaVM/Chromium runtime (Java floats lowered as JS doubles). */
	static float gamma22Teavm(int byteValue) {
		return GAMMA_2_2_TEAVM[byteValue & 255];
	}

	private static final boolean IS_JAVASCRIPT = EagRuntime.getPlatformType() == EnumPlatformType.JAVASCRIPT;

	/**
	 * Single branch, evaluated once per class initialization. Selecting between two
	 * precomputed constant arrays is not "computing table entries at runtime".
	 */
	private static final float[] ACTIVE = IS_JAVASCRIPT ? GAMMA_2_2_TEAVM : GAMMA_2_2_JAVA;
	private static final double[] ACTIVE_THRESH_COMP = IS_JAVASCRIPT ? THRESH_BLEND : THRESH_COMP;
	private static final short[] ACTIVE_BUCKET_COMP = IS_JAVASCRIPT ? BUCKET_BLEND : BUCKET_COMP;

	/**
	 * Package-internal stable references for the hot filter. Callers keep these final
	 * references and never mutate the shared arrays; no array copy is made.
	 */
	static float[] activeTable() {
		return ACTIVE;
	}

	static double[] blendThresholds() {
		return THRESH_BLEND;
	}

	static short[] blendBuckets() {
		return BUCKET_BLEND;
	}

	static double[] componentThresholds() {
		return ACTIVE_THRESH_COMP;
	}

	static short[] componentBuckets() {
		return ACTIVE_BUCKET_COMP;
	}

	/** Package-internal hot accessor; TeaVM ADVANCED inlines it. */
	public static float gamma22(int byteValue) {
		return ACTIVE[byteValue & 255];
	}

	private GeneratedGammaTables() {
	}
